SELECT SUM("Motos_2"."InversionUS") AS "TEMP_TC___2622528870__0_",   CAST(EXTRACT(MONTH FROM "Motos_2"."FECHA") AS BIGINT) AS "mn_FECHA_ok",   SUM("Motos_2"."InversionUS") AS "sum_Calculation_0061002123102817_ok",   CAST(EXTRACT(YEAR FROM "Motos_2"."FECHA") AS BIGINT) AS "yr_FECHA_ok" FROM "Motos_2" WHERE ((CAST(EXTRACT(YEAR FROM "Motos_2"."FECHA") AS BIGINT) >= 2010) AND (CAST(EXTRACT(YEAR FROM "Motos_2"."FECHA") AS BIGINT) <= 2015) AND (CAST(EXTRACT(MONTH FROM "Motos_2"."FECHA") AS BIGINT) >= 1) AND (CAST(EXTRACT(MONTH FROM "Motos_2"."FECHA") AS BIGINT) <= 9) AND ("Motos_2"."Categoria" = 'MOTOCICLETAS') AND ("Motos_2"."Marca" IN ('MOTOCICLETAS YAMAHA', 'YAMAHA'))) GROUP BY "mn_FECHA_ok",   "yr_FECHA_ok";
